const r = $input.first().json;

if (!r) {
  throw new Error('Gemini não retornou nenhum objeto de resposta.');
}

if (r.status === 'failed') {
  const detalhes = Array.isArray(r.errors)
    ? r.errors.map(e => e.message || JSON.stringify(e)).join(' | ')
    : 'Erro não informado pela API.';
  throw new Error('Gemini retornou status FAILED: ' + detalhes);
}

if (r.status === 'requires_action') {
  throw new Error('Gemini retornou requires_action. Este fluxo não utiliza ferramentas que exigem ação externa.');
}

if (r.status === 'incomplete') {
  throw new Error('Gemini retornou uma resposta incompleta. Aumente max_output_tokens ou simplifique o prompt.');
}

let text = '';

if (typeof r.output_text === 'string' && r.output_text.trim()) {
  text = r.output_text;
}

if (!text && typeof r.outputText === 'string' && r.outputText.trim()) {
  text = r.outputText;
}

if (!text && Array.isArray(r.steps)) {
  const textos = [];

  for (const step of r.steps) {
    if (!step || step.type !== 'model_output') continue;
    if (!Array.isArray(step.content)) continue;

    for (const part of step.content) {
      if (part && part.type === 'text' && typeof part.text === 'string') {
        textos.push(part.text);
      }
    }
  }

  text = textos.join('').trim();
}

if (!text && Array.isArray(r.outputs)) {
  const textos = [];

  for (const output of r.outputs) {
    if (output && typeof output.text === 'string') {
      textos.push(output.text);
    }

    if (Array.isArray(output?.content)) {
      for (const part of output.content) {
        if (part && part.type === 'text' && typeof part.text === 'string') {
          textos.push(part.text);
        }
      }
    }
  }

  text = textos.join('').trim();
}

if (!text) {
  throw new Error(
    'Gemini respondeu, mas nenhum texto foi encontrado. Status: ' +
    String(r.status || 'desconhecido') +
    '. Resposta recebida: ' + JSON.stringify(r).slice(0, 3000)
  );
}

let cleaned = String(text).trim();

cleaned = cleaned
  .replace(/^```json\\s*/i, '')
  .replace(/^```\\s*/i, '')
  .replace(/\\s*```$/i, '')
  .trim();

const inicio = cleaned.indexOf('{');
const fim = cleaned.lastIndexOf('}');

if (inicio !== -1 && fim !== -1 && fim > inicio) {
  cleaned = cleaned.slice(inicio, fim + 1);
}

let content;

try {
  content = JSON.parse(cleaned);
} catch (e) {
  throw new Error(
    'Gemini retornou texto, mas o conteúdo não pôde ser convertido em JSON. Conteúdo recebido: ' +
    cleaned.slice(0, 2000)
  );
}

if (!content || typeof content !== 'object' || Array.isArray(content)) {
  throw new Error('A resposta estruturada do Gemini não é um objeto JSON.');
}

return [{
  json: {
    ...content,
    gerado_por: 'Google Gemini API',
    modelo: r.model || 'gemini-3.8-flash',
    status_api: r.status || 'completed',
    interaction_id: r.id || null,
    gerado_em: new Date().toISOString()
  }
}];

const d = $input.first().json;

const obrigatorios = [
  'titulo',
  'gancho',
  'roteiro',
  'legenda',
  'cta',
  'hashtags',
  'ideia_visual',
  'duracao_segundos'
];

const faltantes = obrigatorios.filter(k => {
  const valor = d[k];

  if (valor === undefined || valor === null) return true;
  if (typeof valor === 'string' && valor.trim() === '') return true;
  if (Array.isArray(valor) && valor.length === 0) return true;

  return false;
});

if (faltantes.length > 0) {
  throw new Error('QA REPROVADO — campos ausentes ou vazios: ' + faltantes.join(', '));
}

if (!Array.isArray(d.hashtags)) {
  throw new Error('QA REPROVADO — hashtags deve ser uma lista.');
}

if (d.hashtags.length < 3 || d.hashtags.length > 10) {
  throw new Error('QA REPROVADO — hashtags deve conter entre 3 e 10 itens.');
}

if (!Number.isInteger(d.duracao_segundos)) {
  throw new Error('QA REPROVADO — duracao_segundos deve ser um número inteiro.');
}

if (d.duracao_segundos < 20 || d.duracao_segundos > 90) {
  throw new Error('QA REPROVADO — duracao_segundos deve estar entre 20 e 90 segundos.');
}

if (String(d.gancho).trim().length < 20) {
  throw new Error('QA REPROVADO — gancho muito curto.');
}

if (String(d.roteiro).trim().length < 250) {
  throw new Error('QA REPROVADO — roteiro muito curto para o formato proposto.');
}

if (String(d.titulo).trim().length < 5) {
  throw new Error('QA REPROVADO — título muito curto.');
}

return [{
  json: {
    ...d,
    qa: {
      aprovado: true,
      status: 'APROVADO',
      campos_verificados: obrigatorios,
      verificacoes: {
        estrutura_json: true,
        campos_obrigatorios: true,
        hashtags_validas: true,
        duracao_valida: true,
        gancho_valido: true,
        roteiro_valido: true
      }
    },
    status: 'CONTEUDO_REAL_PRONTO'
  }
}];
